from Crypto.Util.number import *

def unfold(mat):
    m = mat.nrows()
    elements = []
    for i in range(m):
        for j in range(m):
            elements.append(mat[i, j])
    return bytes(elements)

def G(p, q, s):
    gp, gq = 1, 1
    for i in range(0, s):
        gp *= (p ** s - p ** i)
        gq *= (q ** s - q ** i)
    return gp * gq

